"""Chart-pattern family: enter long on patterns.triangle_break, on the close that completes it."""

from datetime import timedelta

from lab import patterns
from pandas import DataFrame

from freqtrade.strategy import IStrategy


class ChartSymmetricTriangle_15m(IStrategy):
    INTERFACE_VERSION = 3
    timeframe = "15m"
    can_short = False
    startup_candle_count = 150
    minimal_roi = {"0": 0.03, "360": 0.015}
    stoploss = -0.02
    max_hold = timedelta(hours=18.0)

    def populate_indicators(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe["pattern"] = patterns.triangle_break(dataframe, kind="symmetric", direction="up", k=5, n=3, window=120, flat=0.01).astype(int)
        return dataframe

    def populate_entry_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        dataframe.loc[dataframe["pattern"] > 0, "enter_long"] = 1
        return dataframe

    def populate_exit_trend(self, dataframe: DataFrame, metadata: dict) -> DataFrame:
        return dataframe

    def custom_exit(self, pair: str, trade, current_time, current_rate, current_profit, **kwargs):
        if current_time - trade.open_date_utc >= self.max_hold:
            return "time_stop"
        return None
